// =======================================================
// REPLACE DATA GPS MODUL DENGAN GPS HP
// Format MQTT Paddock TETAP 11 FIELD dan urutannya TIDAK BERUBAH:
// lat,lng,speed,sat,throttle,current_mA,voltage,power,energy,distance,millis
//
// lat/lng/speed = GPS HP
// sat = 1 : GPS HP lock/fresh
// sat = 0 : GPS HP belum lock / update stale
// Tidak pernah fallback ke GPS modul mobil.
// =======================================================

if (msg.payload === undefined || msg.payload === null) return null;

let str = msg.payload.toString().trim();
let parts = str.split(",");
if (parts.length < 11) return null;

let phoneLat = Number(flow.get("phoneGpsLat"));
let phoneLng = Number(flow.get("phoneGpsLng"));
let phoneSpeedKmh = Number(flow.get("phoneGpsSpeedKmh"));
let phoneAccuracy = Number(flow.get("phoneGpsAccuracy"));
let lastFix = Number(flow.get("phoneGpsLastFix")) || 0;
let gpsOk = flow.get("phoneGpsLocked") === true;

let hasPhonePosition = Number.isFinite(phoneLat) && Number.isFinite(phoneLng) &&
                       phoneLat >= -90 && phoneLat <= 90 &&
                       phoneLng >= -180 && phoneLng <= 180 &&
                       !(phoneLat === 0 && phoneLng === 0);

// Jika tidak ada fix baru >15 detik, status dianggap tidak lock.
let fresh = hasPhonePosition && gpsOk && lastFix > 0 && (Date.now() - lastFix) <= 15000;

// Timpa SEMUA field yang memang berasal dari GPS: lat, lng, speed, sat.
// Jika GPS belum lock, jangan fallback ke modul mobil.
parts[0] = hasPhonePosition ? phoneLat.toFixed(7) : "0.0000000";
parts[1] = hasPhonePosition ? phoneLng.toFixed(7) : "0.0000000";
parts[2] = (fresh && Number.isFinite(phoneSpeedKmh)) ? Math.max(0, phoneSpeedKmh).toFixed(2) : "0.00";
parts[3] = fresh ? "1" : "0";

// Diagnostik internal; tidak mengubah struktur paket MQTT.
flow.set("phoneGpsFresh", fresh);
flow.set("phoneGpsLastAccuracy", Number.isFinite(phoneAccuracy) ? phoneAccuracy : 0);

msg.payload = parts.join(",");
return msg;

// Payload sudah diganti lat/lng/sat oleh node Replace GPS.
// Jangan ubah format 11-field yang dikirim ke MQTT Paddock.
return msg;

// =======================================================
// 0. INISIALISASI STATE (jika belum ada)
// =======================================================
if (flow.get("isRunning") === undefined) flow.set("isRunning", false);
if (!flow.get("clockOffset")) flow.set("clockOffset", 0);
if (!flow.get("lapStartTime")) flow.set("lapStartTime", Date.now());
if (!flow.get("carryOver")) flow.set("carryOver", 0);
if (!flow.get("energyOffset")) flow.set("energyOffset", 0);
if (!flow.get("distanceOffset")) flow.set("distanceOffset", 0);
if (!flow.get("lastLapTime")) flow.set("lastLapTime", "--:--.---");
if (!flow.get("lastLapEnergy")) flow.set("lastLapEnergy", "0.00");
if (!flow.get("lastLapKmPerKwh")) flow.set("lastLapKmPerKwh", "0.00");

// =======================================================
// 1. TANGANI PERINTAH DARI MQTT (dari Laptop)
// =======================================================
if (msg.payload && msg.payload.cmd) {
    let cmd = msg.payload;
    if (cmd.cmd === "START") {
        // Reset semua state di HP, set offset berdasarkan timestamp dari laptop
        let offset = cmd.timestamp - Date.now();
        flow.set("clockOffset", offset);
        flow.set("lapStartTime", cmd.timestamp);
        flow.set("carryOver", 0);
        // Energi mulai dihitung tepat saat START diterima.
        // Nilai telemetry terakhir menjadi titik nol untuk tampilan Wh.
        flow.set("energyOffset", flow.get("lastEnergyRaw") || 0);
        flow.set("distanceOffset", flow.get("lastDistance") || 0);
        flow.set("lastLapTime", "--:--.---");
        flow.set("lastLapEnergy", "0.00");
        flow.set("lastLapKmPerKwh", "0.00");
        flow.set("isRunning", true);   // ← SET RUNNING
        return [null, null, null];
    }
    else if (cmd.cmd === "LAP") {
        // Perbarui offset setiap kali LAP (untuk akurasi)
        let newOffset = cmd.timestamp - Date.now();
        flow.set("clockOffset", newOffset);

        let targetTime = flow.get("targetTime") || 200;
        let startTime = flow.get("lapStartTime");
        if (!startTime) {
            flow.set("lapStartTime", cmd.timestamp);
            flow.set("carryOver", 0);
            return [null, null, null];
        }
        let elapsed = (cmd.timestamp - startTime) / 1000;
        let remaining = targetTime - elapsed;
        let carryOver = flow.get("carryOver") || 0;
        carryOver += remaining;
        // Batasi carryOver
        if (carryOver < 1 - targetTime) {
            carryOver = 1 - targetTime;
        }
        flow.set("carryOver", carryOver);

        let lastEnergy = flow.get("lastEnergyRaw") || 0;
        let lastDistance = flow.get("lastDistance") || 0;
        let energyOffset = cmd.energyOffset || 0;
        let distanceOffset = cmd.distanceOffset || 0;
        let lapEnergy = Math.max(0, lastEnergy - energyOffset);
        let lapDistance = Math.max(0, lastDistance - distanceOffset);
        let kmPerKwh = (lapDistance > 0 && lapEnergy > 0) ? (lapDistance / (lapEnergy / 1000)) : 0;

        let lapTimeSec = elapsed;
        let m = Math.floor(lapTimeSec / 60);
        let s = Math.floor(lapTimeSec % 60);
        let ms = Math.floor((lapTimeSec % 1) * 1000);
        let lapStr = `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}.${String(ms).padStart(3, '0')}`;

        flow.set("lastLapTime", lapStr);
        flow.set("lastLapEnergy", lapEnergy.toFixed(2));
        flow.set("lastLapKmPerKwh", kmPerKwh.toFixed(2));

        flow.set("energyOffset", lastEnergy);
        flow.set("distanceOffset", lastDistance);
        flow.set("lapStartTime", cmd.timestamp);

        let totalKmPerKwh = (lastDistance > 0 && lastEnergy > 0) ? (lastDistance / (lastEnergy / 1000)) : 0;

        let lapResult = {
            type: "LAP_RESULT",
            lapTime: lapStr,
            lapEnergy: lapEnergy.toFixed(2),
            lapDistance: lapDistance.toFixed(3),
            kmPerKwh: kmPerKwh.toFixed(2),
            totalEnergy: lastEnergy.toFixed(2),
            totalDistance: lastDistance.toFixed(3),
            totalKmPerKwh: totalKmPerKwh.toFixed(2),
            timestamp: Date.now()
        };
        return [null, null, { payload: lapResult }];
    }
    else if (cmd.cmd === "RESET") {
        // Reset HP berdasarkan perintah dari laptop
        flow.set("lapStartTime", cmd.timestamp);
        flow.set("carryOver", 0);
        let offset = cmd.timestamp - Date.now();
        flow.set("clockOffset", offset);
        flow.set("energyOffset", flow.get("lastEnergyRaw") || 0);
        flow.set("distanceOffset", flow.get("lastDistance") || 0);
        flow.set("lastLapTime", "--:--.---");
        flow.set("lastLapEnergy", "0.00");
        flow.set("lastLapKmPerKwh", "0.00");
        flow.set("isRunning", false);   // ← SET NOT RUNNING
        return [null, null, null];
    }
}

// =======================================================
// 2. PARSING DATA CSV (11 FIELD) UNTUK DASHBOARD HP
//    lat/lng/speed = GPS HP, sat = lock flag 1/0
// =======================================================
let str = msg.payload.toString().trim();
let parts = str.split(",");
if (parts.length < 11) return [null, null, null];

let lat = parseFloat(parts[0]) || 0;
let lng = parseFloat(parts[1]) || 0;
let speed = parseFloat(parts[2]) || 0;
let sat = parseInt(parts[3]) || 0;
let throttle = parseInt(parts[4]) || 0;
let current_mA = parseFloat(parts[5]) || 0;
let voltage = parseFloat(parts[6]) || 0;
let power = parseFloat(parts[7]) || 0;
let energyRaw = parseFloat(parts[8]) || 0;
let distance = parseFloat(parts[9]) || 0;
let millis = parseFloat(parts[10]) || 0;

let current_A = current_mA / 1000.0;

flow.set("lastEnergyRaw", energyRaw);
flow.set("lastDistance", distance);

// --- Energi ---
let energyOffset = flow.get("energyOffset") || 0;
let isRunning = flow.get("isRunning") || false;
let energyDisplay = isRunning ? Math.max(0, energyRaw - energyOffset) : 0;
let targetEnergy = 7;
let remainingEnergy = Math.max(0, targetEnergy - energyDisplay);

// --- Speed gauge ---
let maxSpeed = 50;
let speedPct = Math.min((speed / maxSpeed) * 100, 100);

// --- Timer lap dengan carryOver (hanya jika running) ---
let currentLap = "00:00.000";
let countdown = "00:00.000";
let countdownColor = "#666";

if (isRunning) {
    let targetTime = flow.get("targetTime") || 200;
    let carryOver = flow.get("carryOver") || 0;
    let effectiveTarget = Math.max(1, targetTime + carryOver);
    let startTime = flow.get("lapStartTime");
    if (!startTime) {
        startTime = Date.now();
        flow.set("lapStartTime", startTime);
    }
    let offset = flow.get("clockOffset") || 0;
    let correctedNow = Date.now() + offset;
    let elapsedSec = (correctedNow - startTime) / 1000;
    let remainingSec = effectiveTarget - elapsedSec;

    function fmtTime(sec) {
        let m = Math.floor(Math.abs(sec) / 60);
        let s = Math.floor(Math.abs(sec) % 60);
        let ms = Math.floor((Math.abs(sec) % 1) * 1000);
        let sign = sec < 0 ? '-' : '';
        return `${sign}${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}.${String(ms).padStart(3, '0')}`;
    }
    currentLap = fmtTime(elapsedSec);
    countdown = fmtTime(remainingSec);
    countdownColor = remainingSec <= 0 ? "#ff0044" : (remainingSec <= 60 ? "#ffff00" : "#00ff00");
}

// --- Output dashboard HP (Output 1) ---
let msgTemplate = {
    payload: {
        speed: speed.toFixed(1),
        speedPct: speedPct.toFixed(1),
        current: current_A.toFixed(2),
        power: power.toFixed(0),
        energy: energyDisplay.toFixed(2),
        remEnergy: remainingEnergy.toFixed(2),
        throttle: throttle,
        voltage: voltage.toFixed(1),
        currentLap: currentLap,
        countdown: countdown,
        countdownColor: countdownColor,
        lastLapTime: flow.get("lastLapTime") || "--:--.---",
        lastLapEnergy: flow.get("lastLapEnergy") || "0.00",
        lastLapKmPerKwh: flow.get("lastLapKmPerKwh") || "0.00",
        isRunning: isRunning   // ← tambahkan flag ke payload
    }
};

// --- Peta (Output 2) ---
let msgMap = {
    payload: { name: "RAKATA_EV", lat: lat, lon: lng, heading: 0, icon: "fa-location-arrow", iconColor: "red", track: true, ttl: 600 }
};

// Output 3 = null (kecuali saat menerima perintah)
return [msgTemplate, msgMap, null];

// =======================================================
// GPS HP STATE + SPEED PRECISION FILTER v5
// - coords.speed (Android/browser, m/s) = sumber utama
// - speed dari perpindahan koordinat = validasi/fallback
// - reject fix duplicate / out-of-order
// - adaptive low-pass berbasis dt, bukan alpha tetap
// - spike limiter hanya untuk pembacaan yang tidak fisik
// =======================================================

if (msg.topic === "phone_gps" && msg.payload) {
    let lat = Number(msg.payload.lat);
    let lng = Number(msg.payload.lng);
    let accuracyRaw = msg.payload.accuracy;
    let accuracy = (accuracyRaw === null || accuracyRaw === undefined || accuracyRaw === "") ? NaN : Number(accuracyRaw);
    let speedRawValue = msg.payload.gpsSpeedMs;
    // Penting: Number(null) = 0 di JavaScript. coords.speed=null berarti
    // sensor tidak menyediakan speed, BUKAN kendaraan 0 km/h.
    let browserSpeedMs = (speedRawValue === null || speedRawValue === undefined || speedRawValue === "") ? NaN : Number(speedRawValue);
    let gpsTimestamp = Number(msg.payload.gpsTimestamp) || Date.now();

    let valid = Number.isFinite(lat) && Number.isFinite(lng) &&
                lat >= -90 && lat <= 90 &&
                lng >= -180 && lng <= 180 &&
                !(lat === 0 && lng === 0);

    if (!valid) {
        flow.set("phoneGpsLocked", false);
        node.status({fill:"red", shape:"ring", text:"GPS INVALID"});
        return null;
    }

    // -------------------------------------------------------
    // 1) Tolak fix cache/duplikat/out-of-order.
    //    Ini penting karena watchPosition tidak menjamin setiap
    //    callback adalah pengukuran GNSS baru.
    // -------------------------------------------------------
    let prevTs = Number(flow.get("phoneGpsMeasurementTs")) || 0;
    if (prevTs > 0 && gpsTimestamp <= prevTs) {
        return null;
    }

    let dt = prevTs > 0 ? (gpsTimestamp - prevTs) / 1000 : NaN;

    // -------------------------------------------------------
    // 2) Measurement A: native speed dari Android/browser.
    //    coords.speed = m/s -> km/h.
    // -------------------------------------------------------
    let speedNative = NaN;
    if (Number.isFinite(browserSpeedMs) && browserSpeedMs >= 0) {
        speedNative = browserSpeedMs * 3.6;
        if (speedNative > 80) speedNative = NaN;
    }

    // -------------------------------------------------------
    // 3) Measurement B: speed dari perpindahan posisi.
    //    Hanya dipercaya jika dt dan accuracy masuk akal.
    // -------------------------------------------------------
    let speedPos = NaN;
    let prevLat = Number(flow.get("phoneGpsMeasurementLat"));
    let prevLng = Number(flow.get("phoneGpsMeasurementLng"));
    let prevAcc = Number(flow.get("phoneGpsMeasurementAcc"));

    if (Number.isFinite(prevLat) && Number.isFinite(prevLng) &&
        Number.isFinite(dt) && dt >= 0.20 && dt <= 3.0 &&
        Number.isFinite(accuracy) && accuracy > 0 && accuracy <= 25) {

        const R = 6371000;
        const toRad = x => x * Math.PI / 180;
        let p1 = toRad(prevLat), p2 = toRad(lat);
        let dp = toRad(lat - prevLat);
        let dl = toRad(lng - prevLng);
        let a = Math.sin(dp/2) ** 2 + Math.cos(p1) * Math.cos(p2) * Math.sin(dl/2) ** 2;
        let distM = R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));

        // Noise floor posisi. Jangan mengubah jitter koordinat menjadi speed.
        let noiseFloorM = Math.max(0.8, Math.min(3.0, 0.20 * (accuracy + (Number.isFinite(prevAcc) ? prevAcc : accuracy))));
        if (distM >= noiseFloorM) {
            let candidate = (distM / dt) * 3.6;
            if (candidate >= 0 && candidate <= 80) speedPos = candidate;
        } else if (Number.isFinite(speedNative) && speedNative < 1.0) {
            speedPos = 0;
        }
    }

    // Simpan measurement fix sekarang untuk kalkulasi berikutnya.
    flow.set("phoneGpsMeasurementLat", lat);
    flow.set("phoneGpsMeasurementLng", lng);
    flow.set("phoneGpsMeasurementAcc", Number.isFinite(accuracy) ? accuracy : 0);
    flow.set("phoneGpsMeasurementTs", gpsTimestamp);

    // -------------------------------------------------------
    // 4) FUSION.
    // Native speed adalah primary karena Android biasanya sudah memakai
    // Doppler/fused location. Position-speed hanya mengoreksi ketika
    // keduanya cukup konsisten.
    // -------------------------------------------------------
    let measurement = NaN;
    let source = "NONE";

    if (Number.isFinite(speedNative) && Number.isFinite(speedPos)) {
        let disagreement = Math.abs(speedNative - speedPos);
        if (disagreement <= 5.0) {
            // Accuracy bagus -> position speed boleh memberi kontribusi kecil.
            let posWeight = (accuracy <= 5) ? 0.30 : (accuracy <= 10 ? 0.20 : 0.10);
            measurement = speedNative * (1 - posWeight) + speedPos * posWeight;
            source = "FUSED";
        } else {
            // Jika berbeda jauh, prioritaskan native speed.
            measurement = speedNative;
            source = "NATIVE";
        }
    } else if (Number.isFinite(speedNative)) {
        measurement = speedNative;
        source = "NATIVE";
    } else if (Number.isFinite(speedPos)) {
        measurement = speedPos;
        source = "POSITION";
    }

    if (!Number.isFinite(measurement)) {
        // Tidak ada measurement speed baru. Posisi tetap diperbarui,
        // tetapi jangan menciptakan speed palsu.
        let held = Number(flow.get("phoneGpsSpeedKmh"));
        if (!Number.isFinite(held)) held = 0;
        flow.set("phoneGpsLat", lat);
        flow.set("phoneGpsLng", lng);
        flow.set("phoneGpsAccuracy", Number.isFinite(accuracy) ? accuracy : 0);
        flow.set("phoneGpsLastFix", Date.now());
        flow.set("phoneGpsLocked", true);
        node.status({fill:"green", shape:"dot", text:`LOCK ${held.toFixed(1)} km/h | NO SPEED`});
        return null;
    }

    // -------------------------------------------------------
    // 5) Sanity limit berdasarkan perubahan fisik kendaraan.
    // Hanya memotong spike ekstrem; tidak menghaluskan akselerasi normal.
    // -------------------------------------------------------
    let prevMeasurement = Number(flow.get("phoneGpsLastMeasurementKmh"));
    let dtForLimit = Number.isFinite(dt) ? Math.max(0.10, Math.min(dt, 2.0)) : 1.0;

    if (Number.isFinite(prevMeasurement)) {
        // Batas 6 m/s^2 = 21.6 km/h per detik, cukup longgar untuk kendaraan ini.
        let maxDelta = 21.6 * dtForLimit + 2.0;
        let delta = measurement - prevMeasurement;
        if (Math.abs(delta) > maxDelta) {
            measurement = prevMeasurement + Math.sign(delta) * maxDelta;
            source += "*";
        }
    }
    flow.set("phoneGpsLastMeasurementKmh", measurement);

    // -------------------------------------------------------
    // 6) Adaptive time-based low pass.
    // tau kecil => responsif. Pada GPS 1 Hz alpha ~0.94,
    // jadi hampir seluruh measurement baru langsung masuk.
    // Pada update lebih cepat filter otomatis lebih halus.
    // -------------------------------------------------------
    let prevFiltered = Number(flow.get("phoneGpsSpeedKmh"));
    let filtered;

    if (!Number.isFinite(prevFiltered)) {
        filtered = measurement;
    } else {
        let dtFilter = Number.isFinite(dt) ? Math.max(0.05, Math.min(dt, 2.0)) : 1.0;
        const tau = 0.35; // detik
        let alpha = 1 - Math.exp(-dtFilter / tau);

        // Saat perubahan nyata besar, tingkatkan respons sedikit.
        if (Math.abs(measurement - prevFiltered) >= 4.0) alpha = Math.max(alpha, 0.80);
        alpha = Math.min(0.98, Math.max(0.25, alpha));

        filtered = prevFiltered + alpha * (measurement - prevFiltered);
    }

    // Zero-speed clamp hanya sangat dekat nol.
    if (filtered < 0.5 && measurement < 0.8) filtered = 0;
    filtered = Math.max(0, Math.min(80, filtered));

    flow.set("phoneGpsLat", lat);
    flow.set("phoneGpsLng", lng);
    flow.set("phoneGpsSpeedKmh", filtered);
    flow.set("phoneGpsSpeedSource", source);
    flow.set("phoneGpsAccuracy", Number.isFinite(accuracy) ? accuracy : 0);
    flow.set("phoneGpsLastFix", Date.now());
    flow.set("phoneGpsLocked", true);

    node.status({
        fill:"green",
        shape:"dot",
        text:`${source} ${filtered.toFixed(1)} km/h | ±${Number.isFinite(accuracy)?accuracy.toFixed(0):'?'}m`
    });
    return null;
}

if (msg.topic === "phone_gps_error") {
    flow.set("phoneGpsLocked", false);
    let errText = (msg.payload && msg.payload.message) ? msg.payload.message : "GPS belum lock";
    node.status({fill:"yellow", shape:"ring", text:errText});
    return null;
}

return null;
